input.newString:
for (const a of asteroids) {
  if (rectCircleCollide(shipRect, { x: a.x, y: a.y, r: a.radius })) {
    gameOver = true;
    // play crash sound and stop background music
    crashSound.currentTime = 0;
    crashSound.play();
    bgMusic.pause();
    break;
  }
}

